def score(program: str) -> float:
    try:
        import ast
        tree = ast.parse(program)
        size = len(list(ast.walk(tree)))

        if size < 20:
            return 0.2
        if size > 200:
            return 0.1
        if 50 <= size <= 150:
            return 0.8 - abs(size - 100) / 200
        return 0.5
    except:
        return 0.0

